import fs from 'node:fs';
const read=p=>JSON.parse(fs.readFileSync(p,'utf8'));let cars=read('sources/cars.json');
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n==null?'Neconfirmat':Number(n).toLocaleString('ro-RO',{maximumFractionDigits:2});
const euro=n=>n==null?'Neconfirmat':fmt(n)+' €';
let research=[];for(let name of ['porsche','audi','bmw','mercedes'])if(fs.existsSync(`sources/${name}-market.json`))research.push(...read(`sources/${name}-market.json`).vehicles);
for(let m of research){if(m.anabiModel?.includes('CLS 350'))m.anabiId=1275;if(m.anabiModel?.includes('S 400 4MATIC'))m.anabiId=1272;if(m.anabiModel?.includes('S 400 d')){m.anabiId=1274;m.reference={...m.verifiedSecondaryReference,eligibleForColor:false,comparison:m.verifiedSecondaryReference.caution,minimumScope:m.reason};}if(m.reference){let r=m.reference;r.km??=r.mileageKm;r.evidenceUrl??=r.sourceUrl;r.comparison??=m.differences?.join(' ');r.confidence??=m.quality;r.access??=r.sourceUrl?'Date și ID citite din inventarul public mobile.de al dealerului; pagina individuală poate restricționa accesul automat.':undefined;r.body??=m.anabiId===1272?'Coupé':m.anabiId===1275||m.anabiId===1274?'Berlină':undefined;if(m.anabiModel?.includes('M850i'))r.eligibleForColor=false;}
 if(m.observedAlternatives)m.alternatives=m.observedAlternatives.map(a=>({...a,url:a.sourceUrl,km:a.mileageKm,note:a.status||'Ofertă observată în listă; identificator individual nerecuperat.'}));if(m.indexedLowerObservation){m.otherObserved=[...(m.otherObserved||[]),{...m.indexedLowerObservation,note:'Observație mai ieftină indexată; disponibilitate actuală neconfirmată. Nu este minim verificat.'}];}}
for(let x of cars){let m=research.find(m=>m.anabiId===x.id||m.anabiModel?.startsWith(x.id===1277?'BMW 550e':x.id===1273?'BMW M850i':x.id===1271?'BMW 750i':x.id===1270?'BMW 740d':'NO_MATCH'));x.research=m||null;let r=m?.reference;if(r){r.priceEurGross??=r.priceEur;r.firstRegistration??=r.registration;r.comparison??=r.match;r.access??=r.evidence;r.features??=r.equipment;r.confidence??=m.confidence;r.minimumScope??=(r.limitations||[]).join(' ');x.ref=r;x.delta=100*(x.gross/r.priceEurGross-1);x.color=r.eligibleForColor===false||r.directUrl===null?'gray':x.delta>10?'red':x.delta< -10?'green':'orange';}else{x.color='gray';}if(x.status!=='Viitoare')x.color='gray';}
const labels={gray:'Comparație insuficientă',green:'Sub reper cu peste 10%',orange:'În intervalul ±10%',red:'Peste reper cu peste 10%'};
const dot=c=>`<span class="dot ${c}" aria-hidden="true"></span>`;
const shell=(title,body,sub=false)=>`<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} · ANABI Auto</title><link rel="stylesheet" href="${sub?'../':''}style.css"></head><body><header><a class="brand" href="${sub?'../':''}index.html">A<span class="brand-dot">•</span> ANALIZĂ AUTO</a><span>ANABI × mobile.de <b>12 OCT 2026</b></span></header>${body}<footer>Catalog independent · Date consultate la 12.10.2026 · Prețuri cerute, nu prețuri de tranzacționare. <a href="${sub?'../':''}metodologie.html">Metodologie și limite</a></footer></body></html>`;
fs.writeFileSync('catalog/style.css',`@import url('');:root{--bg:#f4f5f3;--ink:#172723;--muted:#65736c;--line:#dce2dc;--green:#178556;--orange:#df920c;--red:#d34e49}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 'Segoe UI',Arial,sans-serif}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline}header{height:78px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 5vw;background:#fff}.brand{font-size:15px;font-weight:800;letter-spacing:2px}.brand-dot{color:#288358;margin:0 7px}header>span{font-size:12px;color:var(--muted)}header b{margin-left:24px;color:var(--ink)}main{max-width:1320px;margin:auto;padding:42px 32px}.eyebrow{font-size:12px;letter-spacing:2px;color:var(--green);font-weight:700;text-transform:uppercase}h1{font-size:clamp(30px,4vw,52px);line-height:1.12;letter-spacing:-1.5px;margin:14px 0 18px;max-width:900px}h2{font-size:25px;letter-spacing:-.5px;margin:0 0 16px}h3{font-size:19px;line-height:1.35;margin:9px 0}p{margin:10px 0}.intro{max-width:850px;color:var(--muted);font-size:17px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:30px 0}.stat{padding:20px 24px;background:white;border:1px solid var(--line);border-radius:12px}.stat strong{font-size:29px;display:block}.stat span{font-size:12px;color:var(--muted)}.notice{background:#e8eee6;border:1px solid #d7e1d2;border-radius:10px;padding:17px 21px;margin:22px 0;font-size:14px}.notice.warn{background:#fff5e8;border-color:#ebd8b9}.toolbar{display:grid;grid-template-columns:2fr 1fr 1fr 1.2fr 1fr;gap:12px;background:#fff;border:1px solid var(--line);border-radius:12px;padding:20px;margin-top:30px}label{font-size:12px;color:var(--muted);font-weight:600;display:block}input,select,button{font:inherit;border:1px solid #ced7cf;border-radius:7px;padding:10px;width:100%;color:var(--ink);background:#fff;margin-top:5px}input:focus,select:focus{outline:2px solid #318865}button,.button{cursor:pointer;font-weight:600}.button{display:inline-block;padding:10px 16px;background:#1b4b3a;color:#fff;border-radius:7px;font-size:13px}.button.light{background:#eef1eb;color:#234739}.legend{display:flex;flex-wrap:wrap;gap:22px;margin:18px 0;font-size:12px;color:var(--muted)}.dot{height:10px;width:10px;border-radius:100%;display:inline-block;margin-right:8px;flex-shrink:0}.green{background:var(--green)}.red{background:var(--red)}.orange{background:var(--orange)}.gray{background:#89948e}.resultline{display:flex;justify-content:space-between;align-items:center;margin:28px 0 14px}.resultline p{color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.card{overflow:hidden;background:#fff;border:1px solid var(--line);border-radius:13px;display:flex;flex-direction:column}.card img{width:100%;height:210px;object-fit:cover;background:#e3e8e2}.card .placeholder{height:90px;background:#e5ebe3;display:flex;align-items:center;padding:24px;font-size:26px;color:#516b5c}.cardbody{padding:22px;flex:1}.meta{font-size:12px;color:var(--muted)}.pill{display:inline-block;border:1px solid #dce4da;border-radius:5px;padding:3px 7px;font-size:10px;text-transform:uppercase;letter-spacing:.5px;color:#566451;margin:0 4px 6px 0}.money{font-size:27px;font-weight:700;letter-spacing:-.6px}.prices{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:18px;border-top:1px solid var(--line);padding-top:16px}.prices small{display:block;color:var(--muted);font-size:11px}.prices .refmoney{font-size:20px}.verdict{font-size:12px;font-weight:650;margin:14px 0}.cardfoot{border-top:1px solid var(--line);padding:14px 22px;display:flex;align-items:center;justify-content:space-between;font-size:13px}.detailhero{display:grid;grid-template-columns:1.2fr 1fr;gap:35px;margin:28px 0}.detailhero img{width:100%;max-height:460px;object-fit:cover;border-radius:14px}.box{background:#fff;border:1px solid var(--line);border-radius:12px;padding:26px;margin:22px 0}.detailhero .box{margin:0}.detailhero h1{font-size:37px}.bigprice{font-size:37px;font-weight:750;letter-spacing:-1px}.sub{font-size:12px;color:var(--muted)}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:22px}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:12px 14px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#f0f3ed;font-size:12px}td:first-child{color:#627067;width:26%}.links{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.observations{white-space:pre-line}.breadcrumbs{font-size:13px;color:var(--muted)}details{margin:14px 0}summary{cursor:pointer;font-weight:600}.empty{padding:50px;text-align:center;grid-column:1/-1}footer{max-width:1256px;margin:40px auto 0;border-top:1px solid var(--line);padding:26px 12px;color:var(--muted);font-size:12px}footer a{text-decoration:underline}ul{padding-left:20px}.archive-note{font-size:12px;color:#707970}.pagination{display:flex;align-items:center;justify-content:center;gap:20px;margin:28px auto}.pagination button{width:auto}#pageinfo{font-size:13px}.risk{color:#974c32}.calculator{display:grid;grid-template-columns:1fr 1fr;gap:15px}@media(max-width:980px){.grid{grid-template-columns:repeat(2,1fr)}.toolbar{grid-template-columns:repeat(3,1fr)}.detailhero{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){header{padding:0 18px}header>span{display:none}main{padding:27px 18px}.grid,.twocol{grid-template-columns:1fr}.toolbar{grid-template-columns:1fr 1fr}.toolbar label:first-child{grid-column:1/-1}.stats{gap:10px}.stat{padding:15px}.legend{gap:10px}.detailhero h1{font-size:30px}.box{padding:18px}.card img{height:230px}h1{letter-spacing:-1px}}@media print{header,.toolbar,.pagination,footer,.calculator{display:none}.box,.card{break-inside:avoid}body{background:white}.detailhero img{max-height:250px}.grid{display:block}.card{margin-bottom:20px}}`);
