fs.writeFileSync('catalog/app.js',`const $=id=>document.getElementById(id),fmt=n=>Number(n).toLocaleString('ro-RO',{maximumFractionDigits:2}),e=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),norm=s=>s.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase();let page=1,filtered=[];const size=24;for(const m of [...new Set(CARS.map(x=>x.brand))].sort())$('make').add(new Option(m,m));for(const y of [...new Set(CARS.map(x=>x.year).filter(Boolean))].sort((a,b)=>b-a))$('year').add(new Option(y,y));$('year').add(new Option('An neprecizat','unknown'));const labels={gray:'Comparație insuficientă',green:'Sub reper cu peste 10%',orange:'În intervalul ±10%',red:'Peste reper cu peste 10%'};function render(){let q=norm($('query').value);filtered=CARS.filter(x=>(!q||norm(x.title+' '+x.model+' '+x.vins.join(' ')).includes(q))&&(!$('make').value||x.brand===$('make').value)&&(!$('year').value||($('year').value==='unknown'?!x.year:String(x.year)===$('year').value))&&($('status').value==='Toate'||x.status===$('status').value));filtered.sort((a,b)=>$('sort').value==='priceAsc'?a.ron-b.ron:$('sort').value==='date'?(a.auctionDate||'9999').localeCompare(b.auctionDate||'9999'):$('sort').value==='year'?(b.year||0)-(a.year||0):b.ron-a.ron);let pages=Math.max(1,Math.ceil(filtered.length/size));page=Math.min(page,pages);$('count').textContent=filtered.length+' anunțuri';$('pageinfo').textContent=page+' / '+pages;$('prev').disabled=page===1;$('next').disabled=page===pages;$('results').innerHTML=filtered.slice((page-1)*size,page*size).map(x=>'<article class="card">'+(x.status!=='Arhivă'?'<a href="auto/'+x.id+'.html"><img src="assets/'+x.id+'.jpg" alt="'+e(x.model)+'" loading="lazy"></a>':'<div class="placeholder">'+e(x.brand)+'</div>')+'<div class="cardbody"><span class="pill">'+e(x.status)+'</span><span class="pill">'+e(x.year||'An neprecizat')+'</span><h3><span class="dot '+x.color+'"></span><a href="auto/'+x.id+'.html">'+e(x.model)+'</a></h3><p class="meta">'+(x.km!=null?fmt(x.km)+' km · ':'')+'Lot #'+x.id+'</p><div class="prices"><div><small>ANABI '+(x.gross!=null?'cu TVA':'afișat · TVA nearmonizat')+'</small><div class="money">'+(x.gross!=null?fmt(x.gross)+' €':fmt(x.ron)+' lei')+'</div></div><div><small>Reper mobile.de</small><div class="money refmoney">'+(x.ref?fmt(x.ref.priceEurGross)+' €':'—')+'</div></div></div><div class="verdict">'+labels[x.color]+(x.color!=='gray'?' · '+(x.delta>0?'+':'')+fmt(x.delta)+'%':'')+'</div><p class="sub">'+(x.ref?'Reper observat; minimul pieței necertificat.':x.status==='Arhivă'?'Fișă istorică; fără comparație curentă de piață.':'Nu există o referință suficientă pentru semafor.')+'</p></div><div class="cardfoot"><span>'+e(x.auctionDate?x.auctionDate.split('-').reverse().join('.'):'Dată neconfirmată')+'</span><a href="auto/'+x.id+'.html">Vezi analiza ↗</a></div></article>').join('')||'<p class="empty">Nicio ofertă pentru filtrele selectate.</p>';}for(let id of ['query','make','year','status','sort'])$(id).addEventListener('input',()=>{page=1;render()});$('prev').onclick=()=>{page--;render();};$('next').onclick=()=>{page++;render();};render();`);
